FUNCTION_BLOCK FB_Bridge_TLCD_SloshingDamper
(* ========================================================================================= *)
(* LUMINA CYBER-PHYSICAL SYSTEMS ADVANCED AUTOMATION ARCHITECTURE                             *)
(* IEC 61131-3 COMPLIANT FUNCTION BLOCK: FB_Bridge_TLCD_SloshingDamper                       *)
(* APPLICATION: Long-Span Suspension Bridge Tuned Liquid Column Gas Damper (TLCGD / P-TLCD)   *)
(* FEATURES:                                                                                 *)
(*   - 2oo3 Triple Modular Redundancy (TMR) Sensor Voting (Acc, Liquid Level, Chamber Press) *)
(*   - Real-Time Sloshing Resonant Frequency Estimation & Polytropic Gas Spring Regulation   *)
(*   - 4-State Discrete Observer (Deck Disp/Vel, Liquid Disp/Vel) with State-Space Matrices  *)
(*   - Non-Linear Model Predictive Damping & Dynamic Pneumatic Throttle Valve Modulation     *)
(*   - Multi-tier Safety Interlocks, Complex Alarm Word Trees, and Graceful Degradation Modes*)
(* ========================================================================================= *)
VAR_INPUT
    bEnable                 : BOOL;     (* Master supervisory automation enable command *)
    bEmergencyStop          : BOOL;     (* Hardwired SIL-3 safety relay circuit healthy [Active TRUE] *)
    bManualOverride         : BOOL;     (* Operator manual valve positioning override request *)
    rDeckAcc_Sens1          : REAL;     (* Bridge deck mid-span transverse/vertical acceleration sensor 1 [m/s2] *)
    rDeckAcc_Sens2          : REAL;     (* Bridge deck mid-span transverse/vertical acceleration sensor 2 [m/s2] *)
    rDeckAcc_Sens3          : REAL;     (* Bridge deck mid-span transverse/vertical acceleration sensor 3 [m/s2] *)
    rLiquidLevel_L1         : REAL;     (* Left column liquid displacement magnetostrictive sensor 1 [m] *)
    rLiquidLevel_L2         : REAL;     (* Left column liquid displacement magnetostrictive sensor 2 [m] *)
    rLiquidLevel_L3         : REAL;     (* Left column liquid displacement magnetostrictive sensor 3 [m] *)
    rChamberPress_L         : REAL;     (* Left sealed gas chamber static gauge pressure [bar] *)
    rChamberPress_R         : REAL;     (* Right sealed gas chamber static gauge pressure [bar] *)
    rBridgeModalFreq        : REAL;     (* Real-time bridge dominant mode excitation frequency [Hz] *)
    rCrossWindSpeed         : REAL;     (* Ultrasonic anemometer mid-span crosswind velocity [m/s] *)
    rManualValvePos         : REAL;     (* Manual valve opening reference command [0.0..100.0 %] *)
    tSamplePeriod           : TIME;     (* Deterministic PLC cyclic execution cycle time [ms] *)
END_VAR

VAR_OUTPUT
    bSystemReady            : BOOL;     (* TLCD active damping system online and healthy *)
    bActiveControlEngaged   : BOOL;     (* Active pneumatic throttling loop currently engaged *)
    rAirValveCmd            : REAL;     (* Modulating electro-pneumatic throttle valve command [0.0..100.0 %] *)
    rSupplyPressSetpt       : REAL;     (* Pneumatic gas replenishment regulator pressure command [bar] *)
    rExhaustPressSetpt      : REAL;     (* Pneumatic gas exhaust relief valve pressure command [bar] *)
    rResonantSloshFreq      : REAL;     (* Instantaneous calculated TLCD sloshing resonance frequency [Hz] *)
    rEstDeckVelocity        : REAL;     (* Discrete observer estimated bridge deck vertical velocity [m/s] *)
    rEstLiquidVelocity      : REAL;     (* Discrete observer estimated liquid column sloshing velocity [m/s] *)
    rDampingPower_kW        : REAL;     (* Real-time mechanical kinetic energy dissipation rate [kW] *)
    wStatusWord             : WORD;     (* Packed 16-bit TLCGD operational status register *)
    wAlarmWord              : WORD;     (* Packed 16-bit comprehensive diagnostic alarm register *)
    bTripAlarm              : BOOL;     (* Common safety trip boolean flag to shutdown dampers *)
END_VAR

VAR
    (* --- State Machine & Timing Control --- *)
    iOperatingState         : INT := 0; (* 0:BOOT, 10:STANDBY, 20:MODAL_TUNE, 30:ACTIVE_MPC, 40:FLUTTER_OVERDRIVE, 80:DEGRADED, 99:TRIP *)
    tStateTimer             : TON;      (* State transition dwell and settling timer *)
    tDiscrepancyTimerAcc    : TON;      (* Acceleration sensor discordance persistence timer *)
    tDiscrepancyTimerLvl    : TON;      (* Liquid level sensor discordance persistence timer *)
    tPressureEqualTimer     : TON;      (* Chamber pressure equalization persistence timer *)

    (* --- Physical & Geometric Damper Constants --- *)
    rFluidDensity           : REAL := 1025.0;  (* TLCD liquid mixture density (Water-Glycol) [kg/m3] *)
    rColumnArea             : REAL := 1.85;    (* Cross-sectional area of vertical column [m2] *)
    rEffectiveLength        : REAL := 26.40;   (* Effective length of oscillating liquid column [m] *)
    rGravity                : REAL := 9.80665; (* Gravitational acceleration constant [m/s2] *)
    rPolytropicIndex        : REAL := 1.40;    (* Diabatic/Adiabatic gas constant kappa [-] *)
    rEquilibriumGasHeight   : REAL := 1.75;    (* Quiescent gas chamber headspace vertical height [m] *)
    rAtmosphericPressure    : REAL := 1.01325; (* Ambient standard atmospheric pressure [bar] *)
    rMaxLiquidDisplacement  : REAL := 1.45;    (* Maximum safe column stroke limit to prevent impact [m] *)
    rPI                     : REAL := 3.1415926535;

    (* --- 2oo3 TMR Voting Variables --- *)
    rVotedDeckAcc           : REAL;     (* Synthesized 2oo3 voted deck acceleration [m/s2] *)
    rVotedLiquidLevel       : REAL;     (* Synthesized 2oo3 voted liquid column displacement [m] *)
    bAccSens1_Fault         : BOOL;     (* Acceleration sensor 1 fault flag *)
    bAccSens2_Fault         : BOOL;     (* Acceleration sensor 2 fault flag *)
    bAccSens3_Fault         : BOOL;     (* Acceleration sensor 3 fault flag *)
    bLvlSens1_Fault         : BOOL;     (* Liquid level sensor 1 fault flag *)
    bLvlSens2_Fault         : BOOL;     (* Liquid level sensor 2 fault flag *)
    bLvlSens3_Fault         : BOOL;     (* Liquid level sensor 3 fault flag *)
    rAccDiff12              : REAL;
    rAccDiff23              : REAL;
    rAccDiff31              : REAL;
    rLvlDiff12              : REAL;
    rLvlDiff23              : REAL;
    rLvlDiff31              : REAL;

    (* --- Discrete State-Space Observer: x(k+1) = Ad*x(k) + Bd*u(k) + L*(y - Cd*x(k)) --- *)
    (* States: x[1] = Deck Displ [m], x[2] = Deck Vel [m/s], x[3] = Slosh Displ [m], x[4] = Slosh Vel [m/s] *)
    rState_x1               : REAL := 0.0;
    rState_x2               : REAL := 0.0;
    rState_x3               : REAL := 0.0;
    rState_x4               : REAL := 0.0;
    rNext_x1                : REAL := 0.0;
    rNext_x2                : REAL := 0.0;
    rNext_x3                : REAL := 0.0;
    rNext_x4                : REAL := 0.0;
    rObsInnov1              : REAL := 0.0; (* Acceleration measurement innovation residual *)
    rObsInnov2              : REAL := 0.0; (* Liquid displacement measurement innovation residual *)

    (* Observer Gain Coefficients (Discrete Luenberger Matrix L) *)
    rL_Gain11               : REAL := 0.042;
    rL_Gain12               : REAL := 0.008;
    rL_Gain21               : REAL := 0.385;
    rL_Gain22               : REAL := 0.065;
    rL_Gain31               : REAL := 0.012;
    rL_Gain32               : REAL := 0.450;
    rL_Gain41               : REAL := 0.055;
    rL_Gain42               : REAL := 0.820;

    (* Bridge Structural Dynamics Equivalent Parameters *)
    rBridgeModalMass        : REAL := 1.85E+06; (* Generalized modal mass of 1st bridge deck mode [kg] *)
    rBridgeModalDamping     : REAL := 4.20E+04; (* Inherent bridge deck damping [N*s/m] *)
    rBridgeModalStiffness   : REAL := 3.65E+06; (* Generalized bridge modal stiffness [N/m] *)

    (* --- Pneumatic Air Spring & Frequency Control Variables --- *)
    rMeanGasPressureBar     : REAL;     (* Average absolute gas chamber pressure [bar] *)
    rGasSpringStiffness     : REAL;     (* Equivalent volumetric gas spring stiffness parameter [N/m] *)
    rOmegaNaturalSq         : REAL;     (* Natural sloshing frequency squared [rad/s]^2 *)
    rOmegaNatural           : REAL;     (* Natural sloshing angular frequency [rad/s] *)
    rTuningRatioGamma       : REAL;     (* Damper-to-bridge tuning ratio (omega_d / omega_b) [-] *)
    rOptimalPressureBar     : REAL;     (* Target absolute gas pressure required to match resonance [bar] *)

    (* --- Model Predictive Damping & Valve Modulation --- *)
    rDt                     : REAL;     (* Sampling period in seconds [s] *)
    rHeadLossCoeffXi        : REAL;     (* Computed non-linear orifice head loss coefficient [-] *)
    rDesiredDampingRatio    : REAL;     (* Optimal damping ratio commanded by wind and excitation [-] *)
    rValveCommandRaw        : REAL;     (* Unclamped valve throttling percentage [%] *)
    rValveSlewRateLimit     : REAL := 25.0; (* Maximum valve positioning slew rate [%/s] *)
    rLastValveCmd           : REAL := 50.0; (* Previous execution cycle valve position command [%] *)
    rDampingForceHydraulic  : REAL;     (* Non-linear turbulent head-loss damping force [N] *)

    (* --- Energy Dissipation & Performance Metrics --- *)
    rInstPowerDissipated    : REAL;     (* Instantaneous power dissipated by liquid orifice [W] *)
    rAccumulatedEnergy_MJ   : REAL := 0.0; (* Integral energy absorbed during event [MJ] *)

    (* --- Alarms and Diagnostics Hysteresis --- *)
    rAccDiscrepancyLimit    : REAL := 0.35; (* Sensor Discordance trip limit [m/s2] *)
    rLvlDiscrepancyLimit    : REAL := 0.12; (* Level Discordance trip limit [m] *)
    rPressAsymmetryLimit    : REAL := 1.80; (* Differential chamber pressure limit [bar] *)
    rDeckAccStormLimit      : REAL := 0.65; (* High vibration storm alarm threshold [m/s2] *)
    rDeckAccTripLimit       : REAL := 1.85; (* Severe structural hazard trip threshold [m/s2] *)
END_VAR

(* ========================================================================================= *)
(* 1.0 HARDWIRED SAFETY INTERLOCKS & IMMEDIATE TRIP MONITORING                               *)
(* ========================================================================================= *)
IF NOT bEmergencyStop THEN
    bSystemReady            := FALSE;
    bActiveControlEngaged   := FALSE;
    rAirValveCmd            := 100.0; (* Fail-Safe fully open orifice to prevent hydraulic ram *)
    rSupplyPressSetpt       := 0.0;
    rExhaustPressSetpt      := 0.0;
    wAlarmWord.9            := TRUE;  (* Bit 9: HARDWARE_ESTOP_ACTIVE *)
    bTripAlarm              := TRUE;
    iOperatingState         := 99;    (* EMERGENCY TRIP STATE *)
    RETURN;
END_IF;

(* Convert cycle time from TIME to REAL seconds *)
rDt := TIME_TO_REAL(tSamplePeriod) / 1000.0;
IF rDt <= 0.0001 THEN
    rDt := 0.010; (* 10 ms fallback default *)
END_IF;

(* ========================================================================================= *)
(* 2.0 TRIPLE MODULAR REDUNDANT (2oo3) SENSOR VOTING ALGORITHMS                              *)
(* ========================================================================================= *)
(* 2.1 Bridge Deck Acceleration 2oo3 Voter *)
rAccDiff12 := ABS(rDeckAcc_Sens1 - rDeckAcc_Sens2);
rAccDiff23 := ABS(rDeckAcc_Sens2 - rDeckAcc_Sens3);
rAccDiff31 := ABS(rDeckAcc_Sens3 - rDeckAcc_Sens1);

bAccSens1_Fault := (rAccDiff12 > rAccDiscrepancyLimit) AND (rAccDiff31 > rAccDiscrepancyLimit);
bAccSens2_Fault := (rAccDiff12 > rAccDiscrepancyLimit) AND (rAccDiff23 > rAccDiscrepancyLimit);
bAccSens3_Fault := (rAccDiff23 > rAccDiscrepancyLimit) AND (rAccDiff31 > rAccDiscrepancyLimit);

tDiscrepancyTimerAcc(IN := (bAccSens1_Fault OR bAccSens2_Fault OR bAccSens3_Fault), PT := T#500MS);
wAlarmWord.0 := tDiscrepancyTimerAcc.Q; (* Bit 0: ACCEL_SENSOR_DISCREPANCY *)

IF NOT bAccSens1_Fault AND NOT bAccSens2_Fault AND NOT bAccSens3_Fault THEN
    (* Full Health: Exact median selection between 3 sensors *)
    IF ((rDeckAcc_Sens1 >= rDeckAcc_Sens2) AND (rDeckAcc_Sens1 <= rDeckAcc_Sens3)) OR
       ((rDeckAcc_Sens1 <= rDeckAcc_Sens2) AND (rDeckAcc_Sens1 >= rDeckAcc_Sens3)) THEN
        rVotedDeckAcc := rDeckAcc_Sens1;
    ELSIF ((rDeckAcc_Sens2 >= rDeckAcc_Sens1) AND (rDeckAcc_Sens2 <= rDeckAcc_Sens3)) OR
          ((rDeckAcc_Sens2 <= rDeckAcc_Sens1) AND (rDeckAcc_Sens2 >= rDeckAcc_Sens3)) THEN
        rVotedDeckAcc := rDeckAcc_Sens2;
    ELSE
        rVotedDeckAcc := rDeckAcc_Sens3;
    END_IF;
ELSIF bAccSens1_Fault AND NOT bAccSens2_Fault AND NOT bAccSens3_Fault THEN
    rVotedDeckAcc := (rDeckAcc_Sens2 + rDeckAcc_Sens3) * 0.5;
ELSIF bAccSens2_Fault AND NOT bAccSens1_Fault AND NOT bAccSens3_Fault THEN
    rVotedDeckAcc := (rDeckAcc_Sens1 + rDeckAcc_Sens3) * 0.5;
ELSIF bAccSens3_Fault AND NOT bAccSens1_Fault AND NOT bAccSens2_Fault THEN
    rVotedDeckAcc := (rDeckAcc_Sens1 + rDeckAcc_Sens2) * 0.5;
ELSE
    (* Multiple sensor discordance: fallback to mean and flag alarm *)
    rVotedDeckAcc := (rDeckAcc_Sens1 + rDeckAcc_Sens2 + rDeckAcc_Sens3) / 3.0;
    wAlarmWord.8  := TRUE; (* Bit 8: TMR_VOTER_DEGRADED *)
END_IF;

(* 2.2 Liquid Column Surface Displacement 2oo3 Voter *)
rLvlDiff12 := ABS(rLiquidLevel_L1 - rLiquidLevel_L2);
rLvlDiff23 := ABS(rLiquidLevel_L2 - rLiquidLevel_L3);
rLvlDiff31 := ABS(rLiquidLevel_L3 - rLiquidLevel_L1);

bLvlSens1_Fault := (rLvlDiff12 > rLvlDiscrepancyLimit) AND (rLvlDiff31 > rLvlDiscrepancyLimit);
bLvlSens2_Fault := (rLvlDiff12 > rLvlDiscrepancyLimit) AND (rLvlDiff23 > rLvlDiscrepancyLimit);
bLvlSens3_Fault := (rLvlDiff23 > rLvlDiscrepancyLimit) AND (rLvlDiff31 > rLvlDiscrepancyLimit);

tDiscrepancyTimerLvl(IN := (bLvlSens1_Fault OR bLvlSens2_Fault OR bLvlSens3_Fault), PT := T#500MS);
wAlarmWord.1 := tDiscrepancyTimerLvl.Q; (* Bit 1: LEVEL_SENSOR_DISCREPANCY *)

IF NOT bLvlSens1_Fault AND NOT bLvlSens2_Fault AND NOT bLvlSens3_Fault THEN
    IF ((rLiquidLevel_L1 >= rLiquidLevel_L2) AND (rLiquidLevel_L1 <= rLiquidLevel_L3)) OR
       ((rLiquidLevel_L1 <= rLiquidLevel_L2) AND (rLiquidLevel_L1 >= rLiquidLevel_L3)) THEN
        rVotedLiquidLevel := rLiquidLevel_L1;
    ELSIF ((rLiquidLevel_L2 >= rLiquidLevel_L1) AND (rLiquidLevel_L2 <= rLiquidLevel_L3)) OR
          ((rLiquidLevel_L2 <= rLiquidLevel_L1) AND (rLiquidLevel_L2 >= rLiquidLevel_L3)) THEN
        rVotedLiquidLevel := rLiquidLevel_L2;
    ELSE
        rVotedLiquidLevel := rLiquidLevel_L3;
    END_IF;
ELSIF bLvlSens1_Fault AND NOT bLvlSens2_Fault AND NOT bLvlSens3_Fault THEN
    rVotedLiquidLevel := (rLiquidLevel_L2 + rLiquidLevel_L3) * 0.5;
ELSIF bLvlSens2_Fault AND NOT bLvlSens1_Fault AND NOT bLvlSens3_Fault THEN
    rVotedLiquidLevel := (rLiquidLevel_L1 + rLiquidLevel_L3) * 0.5;
ELSIF bLvlSens3_Fault AND NOT bLvlSens1_Fault AND NOT bLvlSens2_Fault THEN
    rVotedLiquidLevel := (rLiquidLevel_L1 + rLiquidLevel_L2) * 0.5;
ELSE
    rVotedLiquidLevel := (rLiquidLevel_L1 + rLiquidLevel_L2 + rLiquidLevel_L3) / 3.0;
    wAlarmWord.8      := TRUE;
END_IF;

(* ========================================================================================= *)
(* 3.0 PNEUMATIC POLYTROPIC GAS SPRING & RESONANT FREQUENCY EQUATIONS                        *)
(* ========================================================================================= *)
(* Absolute static chamber pressure (Gauge + Atmospheric) *)
rMeanGasPressureBar := ((rChamberPress_L + rChamberPress_R) * 0.5) + rAtmosphericPressure;
IF rMeanGasPressureBar < 0.50 THEN
    rMeanGasPressureBar := 0.50; (* Safeguard against zero/negative division *)
END_IF;

(* TLCGD Natural Frequency with Polytropic Gas Spring:                                       *)
(* omega_d^2 = (2 * g / Le) + (2 * kappa * P0 / (rho * Le * H0))                             *)
(* Note: P0 converted from bar to N/m2 (P_Pa = P_bar * 1.0E+05)                              *)
rGasSpringStiffness := (2.0 * rPolytropicIndex * (rMeanGasPressureBar * 1.0E+05)) /
                       (rFluidDensity * rEffectiveLength * rEquilibriumGasHeight);

rOmegaNaturalSq := ((2.0 * rGravity) / rEffectiveLength) + rGasSpringStiffness;
IF rOmegaNaturalSq > 0.01 THEN
    rOmegaNatural := SQRT(rOmegaNaturalSq);
ELSE
    rOmegaNatural := 0.1;
END_IF;

rResonantSloshFreq := rOmegaNatural / (2.0 * rPI);

(* Calculate required gas pressure target to tune to current bridge modal frequency *)
IF rBridgeModalFreq > 0.05 THEN
    (* Target omega_target = 2 * PI * rBridgeModalFreq *)
    (* P_target = ( (omega_target^2 - 2g/Le) * rho * Le * H0 ) / (2 * kappa)                 *)
    rOptimalPressureBar := ((((2.0 * rPI * rBridgeModalFreq) * (2.0 * rPI * rBridgeModalFreq)) -
                            ((2.0 * rGravity) / rEffectiveLength)) *
                            (rFluidDensity * rEffectiveLength * rEquilibriumGasHeight)) /
                           (2.0 * rPolytropicIndex * 1.0E+05);

    (* Clamp target absolute pressure between 1.05 bar and 4.50 bar *)
    IF rOptimalPressureBar < 1.05 THEN
        rOptimalPressureBar := 1.05;
    ELSIF rOptimalPressureBar > 4.50 THEN
        rOptimalPressureBar := 4.50;
    END_IF;
    rSupplyPressSetpt := rOptimalPressureBar - rAtmosphericPressure;
ELSE
    rOptimalPressureBar := rAtmosphericPressure + 0.5;
    rSupplyPressSetpt   := 0.50;
END_IF;

(* Differential Chamber Pressure Monitoring & Relief *)
IF ABS(rChamberPress_L - rChamberPress_R) > rPressAsymmetryLimit THEN
    tPressureEqualTimer(IN := TRUE, PT := T#2S);
    IF tPressureEqualTimer.Q THEN
        wAlarmWord.2       := TRUE; (* Bit 2: PRESSURE_ASYMMETRY_HIGH *)
        rExhaustPressSetpt := 0.20; (* Bleed excess air *)
    END_IF;
ELSE
    tPressureEqualTimer(IN := FALSE);
    wAlarmWord.2       := FALSE;
    rExhaustPressSetpt := 0.0;
END_IF;

(* Stroke limits check *)
IF ABS(rVotedLiquidLevel) > rMaxLiquidDisplacement THEN
    wAlarmWord.3 := TRUE; (* Bit 3: FLUID_LEVEL_STROKE_EXCEEDED *)
ELSE
    wAlarmWord.3 := FALSE;
END_IF;

(* Bridge acceleration severity monitoring *)
IF ABS(rVotedDeckAcc) > rDeckAccTripLimit THEN
    wAlarmWord.5 := TRUE; (* Bit 5: BRIDGE_ACCEL_SEVERITY_ALARM *)
    bTripAlarm   := TRUE;
ELSIF ABS(rVotedDeckAcc) > rDeckAccStormLimit THEN
    wAlarmWord.6 := TRUE; (* Bit 6: AERODYNAMIC_FLUTTER_WARNING *)
ELSE
    wAlarmWord.5 := FALSE;
    wAlarmWord.6 := FALSE;
END_IF;

(* ========================================================================================= *)
(* 4.0 4-STATE DISCRETE STATE-SPACE OBSERVER INTEGRATION                                     *)
(* State vector: x = [Deck Displ, Deck Vel, Sloshing Displ, Sloshing Vel]^T                  *)
(* ========================================================================================= *)
(* Compute innovation residuals from measured deck acceleration and voted liquid displacement *)
rObsInnov1 := rVotedDeckAcc - (- (rBridgeModalStiffness / rBridgeModalMass) * rState_x1
                              - (rBridgeModalDamping / rBridgeModalMass) * rState_x2
                              + ((rFluidDensity * rColumnArea * rGravity) / rBridgeModalMass) * rState_x3);

rObsInnov2 := rVotedLiquidLevel - rState_x3;

(* Discrete numerical integration of observer states using Euler forward with correction gains *)
rNext_x1 := rState_x1 + rDt * (rState_x2 + (rL_Gain11 * rObsInnov1) + (rL_Gain12 * rObsInnov2));
rNext_x2 := rState_x2 + rDt * ((- (rBridgeModalStiffness / rBridgeModalMass) * rState_x1
                                - (rBridgeModalDamping / rBridgeModalMass) * rState_x2
                                + ((rFluidDensity * rColumnArea * rGravity) / rBridgeModalMass) * rState_x3)
                                + (rL_Gain21 * rObsInnov1) + (rL_Gain22 * rObsInnov2));
rNext_x3 := rState_x3 + rDt * (rState_x4 + (rL_Gain31 * rObsInnov1) + (rL_Gain32 * rObsInnov2));
rNext_x4 := rState_x4 + rDt * ((- (rOmegaNaturalSq * rState_x3)
                                - ((rGravity / rEffectiveLength) * rState_x1)
                                - (0.5 * rHeadLossCoeffXi / rEffectiveLength * ABS(rState_x4) * rState_x4))
                                + (rL_Gain41 * rObsInnov1) + (rL_Gain42 * rObsInnov2));

(* Observer update step *)
rState_x1 := rNext_x1;
rState_x2 := rNext_x2;
rState_x3 := rNext_x3;
rState_x4 := rNext_x4;

rEstDeckVelocity   := rState_x2;
rEstLiquidVelocity := rState_x4;

(* Calculate instantaneous hydraulic damping power dissipated *)
rDampingForceHydraulic := 0.5 * rFluidDensity * rColumnArea * rHeadLossCoeffXi * ABS(rState_x4) * rState_x4;
rInstPowerDissipated   := rDampingForceHydraulic * ABS(rState_x4);
rDampingPower_kW       := rInstPowerDissipated / 1000.0;
rAccumulatedEnergy_MJ  := rAccumulatedEnergy_MJ + (rDampingPower_kW * rDt / 1000.0);

(* ========================================================================================= *)
(* 5.0 MULTI-STAGE CYBER-PHYSICAL FINITE STATE MACHINE (CASE)                                *)
(* ========================================================================================= *)
CASE iOperatingState OF

    0: (* STATE: BOOTSTRAP INITIALIZATION & INTEGRITY VERIFICATION *)
        bSystemReady            := FALSE;
        bActiveControlEngaged   := FALSE;
        rAirValveCmd            := 100.0; (* Fully open bypass during startup *)
        rSupplyPressSetpt       := 0.50;
        rExhaustPressSetpt      := 0.0;
        tStateTimer(IN := TRUE, PT := T#3S);
        IF tStateTimer.Q AND bEnable AND (NOT bTripAlarm) THEN
            tStateTimer(IN := FALSE);
            iOperatingState := 10; (* Transition to Standby Monitor *)
        END_IF;

    10: (* STATE: STANDBY MONITOR (Low Ambient Vibration, Quiescent Bridge) *)
        bSystemReady            := TRUE;
        bActiveControlEngaged   := FALSE;
        rAirValveCmd            := 80.0; (* Moderate passive throttling *)
        rSupplyPressSetpt       := 0.50;
        rExhaustPressSetpt      := 0.0;

        (* Engage active tracking if bridge acceleration or crosswind increases *)
        IF (ABS(rVotedDeckAcc) > 0.12) OR (rCrossWindSpeed > 10.0) THEN
            iOperatingState := 20; (* Transition to Modal Tuning *)
        END_IF;

        IF bManualOverride THEN
            rAirValveCmd := rManualValvePos;
        END_IF;

    20: (* STATE: RESONANT FREQUENCY TRACKING & GAS SPRING CHARGING *)
        bSystemReady            := TRUE;
        bActiveControlEngaged   := TRUE;
        rAirValveCmd            := 60.0;

        (* Check frequency lock: when sloshing frequency matches bridge modal frequency +/- 4% *)
        IF (rBridgeModalFreq > 0.05) AND (ABS(rResonantSloshFreq - rBridgeModalFreq) / rBridgeModalFreq < 0.04) THEN
            tStateTimer(IN := TRUE, PT := T#1500MS);
            IF tStateTimer.Q THEN
                tStateTimer(IN := FALSE);
                iOperatingState := 30; (* Transition to Active MPC Damping *)
            END_IF;
        ELSE
            tStateTimer(IN := FALSE);
        END_IF;

        (* If wind gust exceeds severe threshold, jump directly to Overdrive *)
        IF rCrossWindSpeed > 22.0 THEN
            iOperatingState := 40;
        END_IF;

    30: (* STATE: ACTIVE CLOSED-LOOP MODEL PREDICTIVE THROTTLE REGULATION *)
        bSystemReady            := TRUE;
        bActiveControlEngaged   := TRUE;

        (* Adaptive Head-Loss Computation:                                                     *)
        (* Modulate orifice coefficient to maximize velocity phase-lag damping force           *)
        (* Higher deck velocity requires lower valve aperture (higher head-loss xi)           *)
        rDesiredDampingRatio := 0.08 + (0.04 * (rCrossWindSpeed / 30.0));
        IF rDesiredDampingRatio > 0.18 THEN
            rDesiredDampingRatio := 0.18;
        END_IF;

        (* Model Predictive Valve Position Law:                                               *)
        (* Valve% = 100 * (1 - tanh( Gain * |EstDeckVelocity| * |EstLiquidVelocity| ))         *)
        rValveCommandRaw := 95.0 - (65.0 * (ABS(rEstDeckVelocity) * 2.5 + ABS(rEstLiquidVelocity) * 1.2));

        (* Anti-Saturation and Safety Margin Bounds *)
        IF rValveCommandRaw < 10.0 THEN
            rValveCommandRaw := 10.0; (* Prevent absolute choking / hydraulic lock *)
        ELSIF rValveCommandRaw > 95.0 THEN
            rValveCommandRaw := 95.0;
        END_IF;

        (* Slew rate limiter to protect electro-pneumatic actuator *)
        IF (rValveCommandRaw - rLastValveCmd) > (rValveSlewRateLimit * rDt) THEN
            rAirValveCmd := rLastValveCmd + (rValveSlewRateLimit * rDt);
        ELSIF (rLastValveCmd - rValveCommandRaw) > (rValveSlewRateLimit * rDt) THEN
            rAirValveCmd := rLastValveCmd - (rValveSlewRateLimit * rDt);
        ELSE
            rAirValveCmd := rValveCommandRaw;
        END_IF;
        rLastValveCmd := rAirValveCmd;

        (* Update head-loss parameter model based on valve opening fraction *)
        rHeadLossCoeffXi := 1.2 + (85.0 * (1.0 - (rAirValveCmd / 100.0)) * (1.0 - (rAirValveCmd / 100.0)));

        (* Severe Aerodynamic Storm Trigger *)
        IF (rCrossWindSpeed > 25.0) OR (ABS(rVotedDeckAcc) > rDeckAccStormLimit) THEN
            iOperatingState := 40; (* Escalation to Flutter Overdrive *)
        (* Fallback to Standby if bridge calms down for 10 seconds *)
        ELSIF (ABS(rVotedDeckAcc) < 0.08) AND (rCrossWindSpeed < 8.0) THEN
            tStateTimer(IN := TRUE, PT := T#10S);
            IF tStateTimer.Q THEN
                tStateTimer(IN := FALSE);
                iOperatingState := 10;
            END_IF;
        ELSE
            tStateTimer(IN := FALSE);
        END_IF;

        IF wAlarmWord.8 THEN
            iOperatingState := 80; (* Sensor degradation fallback *)
        END_IF;

    40: (* STATE: STORM & AERODYNAMIC FLUTTER OVERDRIVE *)
        bSystemReady            := TRUE;
        bActiveControlEngaged   := TRUE;

        (* In extreme vortex-shedding/flutter conditions, clamp to maximum optimal damping *)
        rAirValveCmd := 25.0; (* High resistance orifice opening *)
        rHeadLossCoeffXi := 45.0;

        (* Verify stroke headroom: if liquid displacement approaches ceiling, vent rapidly *)
        IF ABS(rVotedLiquidLevel) > (rMaxLiquidDisplacement * 0.90) THEN
            rAirValveCmd       := 85.0; (* Pressure relief venting *)
            rExhaustPressSetpt := 0.50;
        END_IF;

        IF (rCrossWindSpeed < 20.0) AND (ABS(rVotedDeckAcc) < (rDeckAccStormLimit * 0.7)) THEN
            tStateTimer(IN := TRUE, PT := T#5S);
            IF tStateTimer.Q THEN
                tStateTimer(IN := FALSE);
                iOperatingState := 30; (* De-escalate to normal active regulation *)
            END_IF;
        ELSE
            tStateTimer(IN := FALSE);
        END_IF;

    80: (* STATE: DEGRADED OPERATION (TMR Voter Compromised or Sensor Lost) *)
        bSystemReady            := TRUE;
        bActiveControlEngaged   := FALSE;
        (* Fixed robust passive damping orifice position *)
        rAirValveCmd            := 55.0;
        rSupplyPressSetpt       := 0.80;
        rExhaustPressSetpt      := 0.0;
        rHeadLossCoeffXi        := 18.5;

        (* If all sensors restored healthy, recover to standby *)
        IF NOT wAlarmWord.8 AND NOT wAlarmWord.0 AND NOT wAlarmWord.1 THEN
            iOperatingState := 10;
        END_IF;

    99: (* STATE: EMERGENCY SHUTDOWN & SYSTEM LOCKOUT *)
        bSystemReady            := FALSE;
        bActiveControlEngaged   := FALSE;
        rAirValveCmd            := 100.0; (* Fully depressurize and open orifice *)
        rSupplyPressSetpt       := 0.0;
        rExhaustPressSetpt      := 0.0;
        rHeadLossCoeffXi        := 1.2;

        (* Reset latch only when e-stop restored and enable reasserted *)
        IF bEmergencyStop AND NOT bTripAlarm THEN
            IF bEnable THEN
                iOperatingState := 0; (* Re-boot *)
            END_IF;
        END_IF;

END_CASE;

(* ========================================================================================= *)
(* 6.0 STATUS WORD PACKING & TELEMETRY BITFIELDS                                             *)
(* ========================================================================================= *)
wStatusWord.0 := bSystemReady;
wStatusWord.1 := bActiveControlEngaged;
wStatusWord.2 := (iOperatingState = 10); (* Standby Mode *)
wStatusWord.3 := (iOperatingState = 20); (* Modal Tuning Mode *)
wStatusWord.4 := (iOperatingState = 30); (* Active MPC Mode *)
wStatusWord.5 := (iOperatingState = 40); (* Storm Flutter Overdrive Mode *)
wStatusWord.6 := (iOperatingState = 80); (* Degraded Mode *)
wStatusWord.7 := (iOperatingState = 99); (* Trip Mode *)
wStatusWord.8 := NOT wAlarmWord.8;      (* TMR Sensors Fully Redundant & Valid *)
wStatusWord.9 := bManualOverride;

END_FUNCTION_BLOCK
